<script setup lang="ts">
import {computed,watch,onUnmounted,ref} from 'vue';import {useApplication} from '../../application';import UploadImportView from './UploadImportView.vue';import ImportDialogView from './ImportDialogView.vue';import MaterialImportSection from './MaterialImportSection.vue';import {useImportDraft} from './useImportDraft';
const props=defineProps<{meetingId:string;newImport?:boolean}>(),emit=defineEmits<{opened:[];closed:[];saved:[];discarded:[];processed:[];background:[kind:'local'|'library']}>(),{uploadQueue:queue,session,discovery,uploads,importDrafts,journals}=useApplication(),localError=ref<string|null>(null),closeAttempted=ref(false),materialState=ref({busy:false,blocked:false,failed:false,hasFiles:false}),view=ref<InstanceType<typeof ImportDialogView>>();
const draft=useImportDraft(importDrafts,uploads,queue,()=>session.current.value?.actor.enterpriseId??null,()=>props.meetingId,journals,discovery.lookup);
const stop=watch(()=>[session.current.value?.actor.enterpriseId,props.meetingId],()=>{localError.value=null;if(session.current.value)void draft.open();else draft.invalidate(true);},{immediate:true});
const running=computed(()=>queue.items.value.some(i=>['QUEUED','VERIFYING','INITIALIZING','ABORTING'].includes(i.status))),pending=computed(()=>['PREPARED','UNCERTAIN','DENIED'].includes(queue.importCommand.state.value)),acknowledged=computed(()=>queue.importCommand.state.value==='ACKNOWLEDGED');
const allReady=computed(()=>queue.items.value.length>0&&queue.items.value.every(i=>!!i.fileId));const closeBlocked=computed(()=>draft.busy.value||draft.pending.value||running.value||queue.importBusy.value||pending.value||materialState.value.busy||queue.items.value.some(i=>!i.fileId&&!i.canRemove));
watch(closeBlocked,blocked=>{if(!blocked)closeAttempted.value=false;});
const closeNotice=computed(()=>closeAttempted.value&&closeBlocked.value?'文件上传或原请求结果尚未确认，请先完成上传或恢复原请求。':null);
const saveDisabled=computed(()=>!draft.saved.value||!!draft.error.value&&draft.rejected.value||!queue.ready.value||queue.blocked.value||!allReady.value||closeBlocked.value);
const startDisabled=computed(()=>draft.loading.value||draft.busy.value||draft.pending.value||!!draft.error.value||!queue.ready.value||queue.blocked.value||queue.importBusy.value||materialState.value.busy||materialState.value.blocked||(!pending.value&&!allReady.value)||['CONFLICT','REJECTED'].includes(queue.importCommand.state.value));
const reason=computed(()=>draft.pending.value?'原保存或放弃请求结果尚未确认，请重试同一请求。':acknowledged.value?'导入任务已受理，不表示处理已完成。':pending.value?'原导入结果尚未确认，请重试同一请求。':running.value?'请等待会议文件上传及校验完成':queue.items.value.some(i=>!i.fileId)?'有文件添加失败，请重试成功或移除':!queue.items.value.length?'请先添加可用的会议录音或转写文件':materialState.value.blocked?'正在确认背景材料状态': '背景材料和会议信息均可稍后补充。');
async function act(run:()=>Promise<unknown>|unknown){try{localError.value=null;await run();}catch(cause){localError.value=cause instanceof Error?cause.message:'操作未完成，请重试。';}}
let mounted=true;
async function submit(){const who=session.current.value?.actor.enterpriseId,id=props.meetingId;await act(async()=>{if(!pending.value&&!acknowledged.value)await draft.save();await queue.submitImport();});if(!mounted||session.current.value?.actor.enterpriseId!==who||props.meetingId!==id||queue.importCommand.snapshot.value?.actor!==who||queue.importCommand.snapshot.value?.resource!==id)return;if(queue.importCommand.state.value==='ACKNOWLEDGED'&&queue.importCommand.ack.value?.taskId){view.value?.forceClose();emit('processed');}}
async function save(){if(draft.pending.value&&draft.command.snapshot.value?.operation==='IMPORT_DRAFT_DISCARD'){await discard();return;}if(!draft.pending.value&&saveDisabled.value)return;await act(async()=>{const result=await draft.save();if(!mounted||!result||result.meetingId!==props.meetingId)return;view.value?.forceClose();emit('saved');});}
async function discard(){if(draft.busy.value||running.value||queue.importBusy.value||pending.value)return;await act(async()=>{const result=await draft.discard();if(!mounted||!result||result.meetingId!==props.meetingId)return;view.value?.forceClose();emit('discarded');});}
watch(()=>[draft.loading.value,queue.items.value.map(f=>f.fileId??f.status).join(','),draft.saved.value?.revisionToken],()=>{if(!props.newImport&&!draft.loading.value&&draft.saved.value&&!draft.pending.value&&!draft.busy.value&&queue.importCommand.state.value==='EMPTY'&&allReady.value&&queue.items.value.map(f=>f.fileId).join(',')!==draft.saved.value.orderedFileIds.join(','))void act(draft.save);});
function showModal(){return view.value?.showModal()??false;}function close(){return view.value?.close()??false;}function forceClose(){view.value?.forceClose();}
defineExpose({showModal,close,forceClose,get open(){return view.value?.open??false;}});onUnmounted(()=>{mounted=false;stop();draft.invalidate();});
</script>
<template><ImportDialogView ref="view" :reason="reason" :error="localError??draft.error.value??queue.error.value??closeNotice" :save-disabled="draft.pending.value?draft.busy.value:saveDisabled" :save-label="draft.pending.value&&draft.command.snapshot.value?.operation==='IMPORT_DRAFT_DISCARD'?'重试放弃导入':undefined" :discard-disabled="running||pending||draft.pending.value&&draft.command.snapshot.value?.operation!=='IMPORT_DRAFT_DISCARD'" :prompt-busy="draft.busy.value" :start-disabled="startDisabled" :close-blocked="closeBlocked" :has-files="queue.items.value.length>0" :new-import="newImport" :retrying="pending" :acknowledged="acknowledged" @opened="emit('opened')" @closed="emit('closed')" @save="save" @discard="discard" @submit="submit" @background="kind=>emit('background',kind)" @blocked-close="closeAttempted=true"><UploadImportView :items="queue.items.value" :ready="queue.ready.value&&!draft.loading.value" :locked="draft.pending.value||draft.busy.value" :blocked="queue.blocked.value" :error="null" :import-state="queue.importCommand.state.value" :import-busy="queue.importBusy.value" :task-id="queue.importCommand.ack.value?.taskId??null" @add="files=>act(()=>queue.add(files))" @retry="(key,file)=>act(()=>queue.retry(key,file))" @discover="key=>act(()=>queue.discover(key,discovery.lookup))" @open="act(draft.open)" @submit="submit" @discard="act(queue.discardRejectedImport)" @remove="key=>act(()=>queue.remove(key))" @move="(key,direction)=>act(()=>queue.move(key,direction))" @abort="key=>act(()=>queue.abort(key))" @new-batch="act(queue.newBatch)"/><template #materials><MaterialImportSection :meeting-id="props.meetingId" :locked="draft.pending.value||draft.busy.value" @state="materialState=$event"/></template><div v-if="draft.error.value&&!draft.pending.value" class="ac-error small mt12"><button type="button" class="btn sm" @click="act(draft.open)">重新读取导入草稿</button></div></ImportDialogView></template>
